import os
import shutil

def cleanup_storage():
    base_path = "storage/telos/"

    # Directories to delete
    dirs_to_delete = [
        os.path.join(base_path, "wip"),
        os.path.join(base_path, "wip_batch")
    ]

    # Files to delete
    files_to_delete = [
        os.path.join(base_path, "batch_append_logs.py"),
        os.path.join(base_path, "verify_consolidation.py"),
        os.path.join(base_path, "rebuild_and_verify.py"),
        os.path.join(base_path, "repair_and_verify.py")
    ]

    print("--- Starting Project Cleanup ---")

    for d in dirs_to_delete:
        try:
            if os.path.exists(d):
                shutil.rmtree(d)
                print(f"Successfully deleted directory: {d}")
            else:
                print(f"Directory not found, skipping: {d}")
        except Exception as e:
            print(f"Error deleting directory {d}: {e}")

    for f in files_to_delete:
        try:
            if os.path.exists(f):
                os.remove(f)
                print(f"Successfully deleted file: {f}")
            else:
                print(f"File not found, skipping: {f}")
        except Exception as e:
            print(f"Error deleting file {f}: {e}")

    print("\n--- Cleanup Complete ---")

if __name__ == "__main__":
    cleanup_storage()
